var (
	seedDigestRE = regexp.MustCompile(`^[0-9a-f]{64}$`)
	seedCreateRE = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._~-]{0,127}$`)
	ErrSeedCLI   = errors.New("first external seed transaction is invalid")
)

var specAcceptedInputs = func() (bootstrapstart.AcceptedIdentity, bootstrapstart.TrustInputs, error) {
	accepted, err := bootstrapstart.NewMarkerStore().ReadIdentity()
	if err != nil {
		return bootstrapstart.AcceptedIdentity{}, bootstrapstart.TrustInputs{}, err
	}
	if err := bootstrapstart.CheckIdentityRekeyPrestart(accepted); err != nil {
		return bootstrapstart.AcceptedIdentity{}, bootstrapstart.TrustInputs{}, err
	}
	inputs, err := bootstrapstart.LoadTrustInputs(accepted)
	return accepted, inputs, err
}

var (
	controllerFounderMinBackoff   = 5 * time.Second
	controllerFounderMaxBackoff   = 5 * time.Minute
	controllerAdmissionMinBackoff = 5 * time.Second
	controllerAdmissionMaxBackoff = 2 * time.Minute
	// controllerFounderJoinTimeout bounds how long shutdown waits for a
	// cancelled founder. With the broker drain, handoff and lame-duck
	// windows it stays well below the unit's TimeoutStopSec=60s.
	controllerFounderJoinTimeout = 20 * time.Second
)

var (
	// dashboardCheck is how often a controller reads the spec's dashboard
	// and its NetBird address; dashboardTokenRead how often it re-reads the
	// token, so a rotated secret takes effect without a new spec.
	dashboardCheck     = 5 * time.Second
	dashboardTokenRead = 5 * time.Minute
)

var defaultCDRetryPolicy = cdRetryPolicy{
